import { useEffect, useRef } from 'react';
import './EarthGlobe.css';

// ---------------------------------------------------------------------------
// Land mask data (1-bit-per-pixel bitmaps, base64-encoded, decoded at module
// load). MASK covers the whole globe at MASK_RES px/degree; PH is a tight
// crop over the Philippines used for the precise "is this land highlighted"
// check once the forgiving screen-space radius already got us close.
// ---------------------------------------------------------------------------
const MASK_W = 1440;
const MASK_H = 720;
const MASK_ROW_BYTES = 180;
const MASK_RES = 4;

const PH_COL0 = 1185;
const PH_ROW0 = 378;
const PH_W = 44;
const PH_H = 68;
const PH_ROW_BYTES = 6;

const PH_PIN_LAT = 14.5995;
const PH_PIN_LON = 120.9842;

const MASK_B64 =
  "";

const PH_B64 =
  "";

function decode(b64: string): Uint8Array {
  const binStr = atob(b64);
  const bytes = new Uint8Array(binStr.length);
  for (let i = 0; i < binStr.length; i++) bytes[i] = binStr.charCodeAt(i);
  return bytes;
}

const maskBytes = decode(MASK_B64);
const phBytes = decode(PH_B64);

function wrapLon(lonDeg: number): number {
  let lon = lonDeg;
  while (lon < -180) lon += 360;
  while (lon >= 180) lon -= 360;
  return lon;
}

function isLand(lonDeg: number, latDeg: number): boolean {
  const lon = wrapLon(lonDeg);
  const col = Math.floor((lon + 180) * MASK_RES);
  const row = Math.floor((latDeg + 90) * MASK_RES);
  if (row < 0 || row >= MASK_H || col < 0 || col >= MASK_W) return false;
  const byteIndex = row * MASK_ROW_BYTES + (col >> 3);
  const bit = 7 - (col & 7);
  return !!((maskBytes[byteIndex] >> bit) & 1);
}

function isPhilippines(lonDeg: number, latDeg: number): boolean {
  const lon = wrapLon(lonDeg);
  const col = Math.floor((lon + 180) * MASK_RES) - PH_COL0;
  const row = Math.floor((latDeg + 90) * MASK_RES) - PH_ROW0;
  if (row < 0 || row >= PH_H || col < 0 || col >= PH_W) return false;
  const byteIndex = row * PH_ROW_BYTES + (col >> 3);
  const bit = 7 - (col & 7);
  return !!((phBytes[byteIndex] >> bit) & 1);
}

// ---------------------------------------------------------------------------
// Sphere geometry (all pure functions of the canvas' internal resolution, so
// they live at module scope rather than being rebuilt on every mount).
// ---------------------------------------------------------------------------
const CW = 640;
const CH = 640;
const cx = CW / 2;
const cy = CH / 2;
const R = 240;

// Forgiving hit-test radius (in canvas px) around the PH pin's projected
// screen position. Anything within this radius counts as "on Philippines"
// without needing to land on the exact (thin, foreshortened) mask pixels.
const PH_HIT_RADIUS = 34;
// Larger radius used once already hovered/selected, so a rotating globe or
// small cursor jitter doesn't flicker the target off right at the edge.
const PH_HIT_RADIUS_STICKY = 46;

interface ProjectedPoint {
  sx: number;
  sy: number;
  depth: number;
}

function forwardProject(latDeg: number, lonDeg: number, rotDeg: number): ProjectedPoint {
  const phi = (latDeg * Math.PI) / 180;
  const lambda = ((lonDeg + rotDeg) * Math.PI) / 180;
  const x = R * Math.cos(phi) * Math.sin(lambda);
  const y = R * Math.sin(phi);
  const z = R * Math.cos(phi) * Math.cos(lambda);
  const depth = (z + R) / (2 * R);
  return { sx: cx + x, sy: cy - y, depth };
}

function pixelToLatLon(px: number, py: number, rotDeg: number): { lat: number; lon: number } | null {
  const dx = px - cx;
  const dy = py - cy;
  const d2 = dx * dx + dy * dy;
  if (d2 > R * R) return null;
  const nz = Math.sqrt(Math.max(R * R - d2, 0));
  const lat = (Math.asin(-dy / R) * 180) / Math.PI;
  const baseLon = (Math.atan2(dx, nz) * 180) / Math.PI;
  const lon = baseLon - rotDeg;
  return { lat, lon };
}

// Robust hit-test: true if (px,py) should count as "on the Philippines".
// Combines a generous screen-space radius around the pin (primary, forgiving)
// with the exact mask lookup as a fallback (covers cases where the visible
// landmass extends further than the radius, e.g. northern Luzon).
function hitTestPhilippines(px: number, py: number, rotDeg: number, sticky: boolean): boolean {
  const proj = forwardProject(PH_PIN_LAT, PH_PIN_LON, rotDeg);
  // Only valid if the pin is actually facing the viewer right now.
  if (proj.depth > 0.15) {
    const ddx = px - proj.sx;
    const ddy = py - proj.sy;
    const radius = sticky ? PH_HIT_RADIUS_STICKY : PH_HIT_RADIUS;
    if (ddx * ddx + ddy * ddy <= radius * radius) return true;
  }
  const ll = pixelToLatLon(px, py, rotDeg);
  if (ll && isPhilippines(ll.lon, ll.lat)) return true;
  return false;
}

// Precomputed per-pixel sphere sample points (lon/lat/depth for every canvas
// pixel that falls inside the globe's silhouette). Pure function of CW/CH/R,
// so — like the mask bytes above — this is built once at module load rather
// than once per mount.
const pixIndex: number[] = [];
const pixBaseLon: number[] = [];
const pixLat: number[] = [];
const pixDepth: number[] = [];

for (let py = 0; py < CH; py++) {
  const dy = py - cy;
  for (let px = 0; px < CW; px++) {
    const dx = px - cx;
    const d2 = dx * dx + dy * dy;
    if (d2 > R * R) continue;
    const nz = Math.sqrt(Math.max(R * R - d2, 0));
    const x = dx;
    const y = -dy;
    const z = nz;
    const lat = (Math.asin(y / R) * 180) / Math.PI;
    const baseLon = (Math.atan2(x, z) * 180) / Math.PI;
    const depth = nz / R;

    pixIndex.push((py * CW + px) * 4);
    pixBaseLon.push(baseLon);
    pixLat.push(lat);
    pixDepth.push(depth);
  }
}

const N = pixIndex.length;

export interface EarthGlobeProps {
  /** Rendered size in CSS pixels (canvas is always 640x640 internally). */
  size?: number;
  /** Label shown on the pin once it's pinned. */
  label?: string;
  /** Small subtitle line under the label. */
  tag?: string;
  className?: string;
}

export default function EarthGlobe({
  size = 640,
  label = 'PHILIPPINES',
  tag = 'HOME COUNTRY',
  className,
}: EarthGlobeProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const pinRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const pinEl = pinRef.current;
    if (!canvas || !pinEl) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const imgData = ctx.createImageData(CW, CH);
    const buf = imgData.data;

    // Canvas internally always renders at CW x CH (640x640); it's scaled
    // down via CSS to `size` for display. The pin div lives outside the
    // canvas, so its coordinates need this same scale factor applied.
    const displayScaleX = size / CW;
    const displayScaleY = size / CH;

    let theta = 0;
    let lastMouse: { px: number; py: number } | null = null;
    let selected = false; // click-locked state — independent of continuous hover
    let wasHovered = false; // hysteresis state for hover flicker
    let rafId = 0;

    const handleMouseMove = (e: MouseEvent) => {
      const rect = canvas.getBoundingClientRect();
      const scaleX = CW / rect.width;
      const scaleY = CH / rect.height;
      lastMouse = {
        px: (e.clientX - rect.left) * scaleX,
        py: (e.clientY - rect.top) * scaleY,
      };
    };

    const handleMouseLeave = () => {
      lastMouse = null;
    };

    const handleClick = (e: MouseEvent) => {
      const rect = canvas.getBoundingClientRect();
      const scaleX = CW / rect.width;
      const scaleY = CH / rect.height;
      const px = (e.clientX - rect.left) * scaleX;
      const py = (e.clientY - rect.top) * scaleY;
      const rotDeg = (theta * 180) / Math.PI;

      if (hitTestPhilippines(px, py, rotDeg, selected)) {
        selected = !selected; // clicking it again dismisses it
      } else {
        selected = false; // clicking elsewhere dismisses it
      }
    };

    canvas.addEventListener('mousemove', handleMouseMove);
    canvas.addEventListener('mouseleave', handleMouseLeave);
    canvas.addEventListener('click', handleClick);

    function frame() {
      if (!ctx || !canvas || !pinEl) return;

      ctx.clearRect(0, 0, CW, CH);

      const grad = ctx.createRadialGradient(cx, cy, R * 0.7, cx, cy, R * 1.2);
      grad.addColorStop(0, 'rgba(232,40,60,0.10)');
      grad.addColorStop(1, 'rgba(232,40,60,0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(cx, cy, R * 1.2, 0, Math.PI * 2);
      ctx.fill();

      buf.fill(0);

      const rotDeg = (theta * 180) / Math.PI;

      // live hover check purely for the highlight-on-hover feedback.
      // Uses a forgiving radius (see hitTestPhilippines) plus hysteresis
      // (wasHovered) so the highlight doesn't flicker on/off as the globe
      // rotates under a stationary cursor near the mask boundary.
      let hoveredPH = false;
      if (lastMouse) {
        hoveredPH = hitTestPhilippines(lastMouse.px, lastMouse.py, rotDeg, wasHovered);
      }
      wasHovered = hoveredPH;
      canvas.classList.toggle('hoverable', hoveredPH);

      const highlightPH = hoveredPH || selected;

      for (let i = 0; i < N; i++) {
        const lon = pixBaseLon[i] - rotDeg;
        const lat = pixLat[i];
        const depth = pixDepth[i];

        if (isLand(lon, lat)) {
          const idx = pixIndex[i];
          const onPH = highlightPH && isPhilippines(lon, lat);

          if (onPH) {
            const shade = 0.7 + depth * 0.3;
            buf[idx] = Math.round(255 * shade);
            buf[idx + 1] = Math.round(160 * shade);
            buf[idx + 2] = Math.round(90 * shade);
            buf[idx + 3] = 255;
          } else {
            const shade = 0.35 + depth * 0.65;
            buf[idx] = Math.round(232 * shade + 10 * (1 - shade));
            buf[idx + 1] = Math.round(40 * shade + 6 * (1 - shade));
            buf[idx + 2] = Math.round(46 * shade + 8 * (1 - shade));
            buf[idx + 3] = 255;
          }
        }
      }

      ctx.putImageData(imgData, 0, 0);

      ctx.beginPath();
      ctx.arc(cx, cy, R, 0, Math.PI * 2);
      ctx.strokeStyle = 'rgba(255,138,91,0.35)';
      ctx.lineWidth = 1.5;
      ctx.stroke();

      // Pin only shows when *selected* (click-locked), not on plain hover —
      // stays anchored to Manila and tracks rotation smoothly on its own.
      // proj.sx/sy are in the canvas' internal 640-unit coordinate space,
      // but the pin is a plain DOM element positioned inside a wrap div
      // sized to `size` (the canvas is CSS-scaled down to match) — so its
      // coordinates need the same scale factor applied, or it drifts off
      // toward the bottom-right at any size other than 640.
      if (selected) {
        const proj = forwardProject(PH_PIN_LAT, PH_PIN_LON, rotDeg);
        pinEl.style.left = `${proj.sx * displayScaleX}px`;
        pinEl.style.top = `${proj.sy * displayScaleY}px`;
        pinEl.classList.add('visible');
      } else {
        pinEl.classList.remove('visible');
      }

      theta += 0.0032;
      rafId = requestAnimationFrame(frame);
    }

    rafId = requestAnimationFrame(frame);

    return () => {
      cancelAnimationFrame(rafId);
      canvas.removeEventListener('mousemove', handleMouseMove);
      canvas.removeEventListener('mouseleave', handleMouseLeave);
      canvas.removeEventListener('click', handleClick);
    };
  }, [size]);

  return (
    <div className={`earth-globe-wrap${className ? ` ${className}` : ''}`} style={{ width: size, height: size }}>
      <canvas ref={canvasRef} width={CW} height={CH} style={{ width: size, height: size }} />
      <div ref={pinRef} className="earth-globe-pin">
        <div className="earth-globe-pin-label">
          {label}
          <span className="earth-globe-pin-tag">{tag}</span>
        </div>
        <svg width="34" height="34" viewBox="0 0 24 24">
          <path
            d="M12 0C7.03 0 3 4.03 3 9c0 6.75 9 15 9 15s9-8.25 9-15c0-4.97-4.03-9-9-9zm0 13a4 4 0 1 1 0-8 4 4 0 0 1 0 8z"
            fill="#e8283c"
          />
        </svg>
      </div>
    </div>
  );
}